insert into public.jobs (id,employer_id,title,category,description,responsibilities,required_skills,preferred_skills,city,neighborhood,service_area,work_mode,pay_type,pay_min,pay_max,schedule,schedule_tags,min_age,start_date,recurrence,openings,deadline,transportation,transportation_notes,image_url,status,moderation_status,featured,is_demo,created_at,published_at) values ('0000bbbb-0000-4000-8000-000000000012','0000aaaa-0000-4000-8000-000000000004','After-school dog walker','pet-care','Walk two to four friendly, leash-trained dogs on a set route near Solano Avenue. You''ll always start with a paired training walk alongside our lead walker, and we text you each dog''s notes before every shift.',array['Pick up dogs from homes along a set route','30–45 minute group walks on sidewalks and in Memorial Park','Refresh water bowls and log each walk in our app','Report anything unusual to the lead walker right away']::text[],array['Reliable','Comfortable with dogs']::text[],array['Pet first aid','Past pet care']::text[],'Albany','Solano Ave area','albany','in_person','hourly',18,20,'Mon/Wed/Fri, 3:30–5:00 pm',array['weekday','afternoon']::text[],14,(current_date + 6),'recurring',2,(current_date + 20),'bike_or_walk','Route starts near Solano & Masonic. Walkable from Albany High.','https://images.unsplash.com/photo-1601758228041-f3b2795255f1?auto=format&fit=crop&w=1200&q=70','published','approved',true,true,'2026-09-23T16:55:17.935Z','2026-09-23T16:55:17.935Z') on conflict (id) do nothing;
